/* 历史交锋真值表（_7m_db 真实赛果，gen_h2h_map.cjs 产出；gzip+base64，解压后挂 window.H2H_MAP）*/
window.__H2H_GZ__="";
(async function(){try{var s=window.__H2H_GZ__;if(!s||window.H2H_MAP)return;var bin=atob(s),n=bin.length,u=new Uint8Array(n);for(var i=0;i<n;i++)u[i]=bin.charCodeAt(i);if(typeof DecompressionStream!=='function')throw new Error('无 DecompressionStream');var buf=await new Response(new Blob([u]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();window.H2H_MAP=JSON.parse(new TextDecoder('utf-8').decode(new Uint8Array(buf)));window.dispatchEvent(new Event('h2h-ready'));}catch(e){console.warn('[h2h] 解压失败:',e);}})();
